package com.taylordproductivty.med_timing_tracker.data

import androidx.room.Entity
import androidx.room.PrimaryKey

@Entity(tableName = "medications")
data class Medication(
    @PrimaryKey(autoGenerate = true) val id: Int = 0,
    val name: String,
    // MVP only implements INTERVAL; FIXED_SCHEDULE is modeled for forward compatibility.
    val dosingMode: DosingMode = DosingMode.INTERVAL,
    val defaultDose: String,
    // Interval mode: minimum minutes between doses, e.g. 240 for "every 4 hours".
    val minIntervalMinutes: Int? = null,
    val maxDailyDoses: Int? = null,
    // Fixed-schedule mode (unused until that mode ships): CSV of "HH:mm" times.
    val fixedTimesOfDay: String? = null,
    val notes: String? = null,
    val isArchived: Boolean = false,
    val createdAt: Long = System.currentTimeMillis(),
)
